const {features,score,assess,best}=DecisionEngine;
const defaults=()=>({ids:['sso','analytics'],capacity:12,goal:'enterprise',history:[]});
let state=defaults();try{const saved=JSON.parse(localStorage.getItem('decision-lab-v1'));if(saved&&Array.isArray(saved.ids)&&Number.isFinite(saved.capacity)&&['enterprise','engagement','innovation'].includes(saved.goal)){state={...defaults(),...saved,ids:saved.ids.filter(id=>features.some(f=>f.id===id)),capacity:Math.max(0,Math.min(25,saved.capacity)),history:Array.isArray(saved.history)?saved.history.slice(0,10):[]}}}catch{}
let page='Overview';const tabs=[['Overview','◫'],['Prioritisation','≡'],['Decision challenger','✧'],['What-if simulator','⑂'],['Decision brief','▤']];
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('decision-lab-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Your changes will last for this session.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function navigate(name){page=name;render()}
function controls(){return `<div class="row"><label for="capacity">Engineering capacity</label><strong id="cap-value">${state.capacity} <small>pts</small></strong></div><input id="capacity" aria-label="Engineering capacity" type="range" min="0" max="25" value="${state.capacity}"><div class="caption">0 points <span style="float:right">25 points</span></div><div class="row"><label for="goal">Strategic lens</label><select id="goal"><option value="enterprise" ${state.goal==='enterprise'?'selected':''}>Enterprise growth</option><option value="engagement" ${state.goal==='engagement'?'selected':''}>Engagement</option><option value="innovation" ${state.goal==='innovation'?'selected':''}>Innovation</option></select></div>`}
function capacityCard(a){return `<div class="card"><h3>Room to build</h3>${controls()}<div class="progress ${!a.fits?'warnbar':''}"><div style="width:${state.capacity?Math.min(100,a.effort/state.capacity*100):a.effort?100:0}%"></div></div><div class="caption ${!a.fits?'warning':''}">${a.fits?`${state.capacity-a.effort} points remaining`:`${a.effort-state.capacity} points over capacity`}</div></div>`}
function metrics(a){return `<div class="metrics"><div class="card"><div class="metric-label">CAPACITY COMMITTED</div><div class="metric-num ${!a.fits?'warning':''}">${a.effort} <span>/ ${state.capacity} pts</span></div><div class="caption">${a.fits?'Within your delivery budget':'Selection exceeds capacity'}</div></div><div class="card"><div class="metric-label">EXPECTED IMPACT</div><div class="metric-num">${a.impact} <span>points</span></div><div class="caption">Illustrative, additive score</div></div><div class="card"><div class="metric-label">EVIDENCE CONFIDENCE</div><div class="metric-num">${a.confidence}<span>%</span></div><div class="caption">${a.selected.length} features in this scenario</div></div></div>`}
function opportunity(){const ranked=[...features].sort((a,b)=>score(b,state.goal)-score(a,state.goal));const maximum=Math.max(...ranked.map(f=>score(f,state.goal)));return `<div class="card opportunity"><div><span class="pill">THE BIG PICTURE</span><h2 style="margin-top:14px">Where is your strongest opportunity?</h2><p>A transparent view of value, confidence and effort.<br>Change your strategic lens to explore a different perspective.</p><div class="legend"><span>Other candidates</span><span>Your selection</span></div></div><div class="bars">${ranked.map(f=>`<div class="bar-row ${state.ids.includes(f.id)?'selected':''}"><span>${f.name}</span><div class="bar-track" role="img" aria-label="Priority ${score(f,state.goal)}"><span style="width:${score(f,state.goal)/maximum*100}%"></span></div><b>${score(f,state.goal)}</b></div>`).join('')}</div></div>`}
function backlog(){return `<div class="card"><div class="section-head"><div><h2>Make room for what matters</h2><p>Select candidates to shape your roadmap.</p></div><span class="pill">${features.length} candidates</span></div>${[...features].sort((a,b)=>score(b,state.goal)-score(a,state.goal)).map(f=>`<div class="feature"><input type="checkbox" aria-label="Select ${f.name}" data-feature="${f.id}" ${state.ids.includes(f.id)?'checked':''}><div><h3>${f.name}</h3><p>${f.category} · ${f.confidence}% confidence</p><button class="evidence-link" data-evidence="${f.id}">${f.signals} customer signals ↗</button></div><div class="number">${f.effort}<small>EFFORT</small></div><div class="number">${score(f,state.goal)}<small>PRIORITY</small></div></div>`).join('')}<div class="note">Priority = (60% impact + 40% strategic alignment) × confidence ÷ effort × 100. These illustrative inputs support comparison; they are not a forecast.</div></div>`}
function challenger(a){let out=[];if(!a.selected.length)out.push(['Start with a candidate','Select at least one feature to examine its evidence and assumptions.']);if(!a.fits)out.push(['The roadmap does not fit',`Your selection requires ${a.effort} points against ${state.capacity} available. Reduce scope or explicitly renegotiate capacity before committing.`]);for(const f of a.selected)out.push([f.assumption,f.question+` Evidence: ${f.evidence.slice(0,4)} · confidence ${f.confidence}%.`]);if(a.selected.length)out.push(['What would change your mind?','Record a measurable success criterion and a review date. Customer requests alone do not establish business impact.']);return out}
function recommendation(a){const b=best(state.capacity,state.goal);return b.selected.length?`${b.selected.map(f=>f.name).join(' + ')} is the highest-scoring feasible combination under the current formula (${b.effort}/${state.capacity} points). Review the evidence and dependencies before deciding.`:'No candidate fits the current capacity. Increase capacity or reduce feature scope.'}
function briefText(a){return `# Product Decision Lab — Decision brief\n\nFictional product: Northstar\nStrategic lens: ${state.goal}\nCapacity: ${state.capacity} points\nSelected: ${a.selected.map(f=>f.name).join(', ')||'None'}\nEffort: ${a.effort} points\nCapacity status: ${a.fits?'Feasible':'Over capacity — not ready to commit'}\n\n## Comparison\n${recommendation(a)}\n\n## Supporting evidence\n${a.selected.map(f=>f.evidence).join('\n\n')||'No features selected.'}\n\n## Assumptions and validation\n${challenger(a).map(([h,p])=>h+'\n'+p).join('\n\n')}\n\n## Next steps\nValidate procurement or usage assumptions; confirm delivery estimates and dependencies with engineering; set a measurable success metric and review date. The PM owns the final decision.\n\nPrototype: deterministic scoring and rule-based challenger, no live AI inference. All evidence is synthetic. Impact is illustrative and additive; cross-feature dependencies are not modelled.\n`}
function render(){$('.goal').textContent={enterprise:'↗ Goal: grow enterprise adoption',engagement:'↗ Goal: deepen product engagement',innovation:'↗ Goal: explore new capabilities'}[state.goal];const a=assess(state.ids,state.capacity,state.goal);$('#nav').innerHTML=tabs.map(([name,icon])=>`<button data-nav="${name}" class="${page===name?'active':''}" ${page===name?'aria-current="page"':''}><i>${icon}</i>${name}</button>`).join('');let content='';if(page==='Overview'||page==='Prioritisation'){content=metrics(a)+opportunity()+`<div class="layout">${backlog()}<div class="side-stack">${capacityCard(a)}<div class="card dark"><span class="pill">✧ DECISION CHALLENGER</span><h2 style="margin-top:22px">A second perspective.<br>A stronger decision.</h2><p>Surface the assumptions behind your choices before they become commitments.</p><div class="eyebrow-in">RULE-BASED DEMO · NO LIVE AI</div><button data-nav="Decision challenger">Challenge this decision ↗</button></div></div></div>`}else if(page==='Decision challenger'){content=`<div class="layout"><div class="card"><div class="section-head"><h2>Pressure-test your thinking</h2><span class="pill">Rule-based demo</span></div><p class="subtext">Generated from your current selection, evidence confidence and capacity. No live model is connected.</p>${challenger(a).map(([h,p])=>`<div class="challenge"><h3>${esc(h)}</h3><p>${esc(p)}</p></div>`).join('')}<div class="note"><strong>Alternative to explore</strong><br>${recommendation(a)}</div><button data-nav="What-if simulator" class="primary">Explore the trade-offs →</button></div><div class="side-stack">${capacityCard(a)}<div class="card"><h3>Your current selection</h3><p class="subtext">${a.selected.map(f=>f.name).join(' · ')||'No features selected'}</p></div></div></div>`}else if(page==='What-if simulator'){const b=best(state.capacity,state.goal);content=`<div class="grid2"><div class="card"><span class="pill">EXPLORE A SCENARIO</span><h2 style="margin-top:20px">What if capacity changes?</h2><div class="big-number">${state.capacity}<span style="font-size:16px;letter-spacing:0;color:#87977c"> points</span></div>${controls()}<div class="note ${!a.fits?'warning':''}">Your current selection uses ${a.effort} points. ${a.fits?'It fits this scenario.':`It exceeds capacity by ${a.effort-state.capacity} points.`}</div><button id="save-scenario">Save scenario snapshot</button></div><div class="card"><div class="section-head"><h2>A feasible alternative</h2><span class="pill">Calculated</span></div><p class="subtext">Every feature combination is checked against your capacity.</p>${b.selected.map(f=>`<div class="scenario"><h3>${f.name}</h3><p>${f.effort} effort · ${f.impact} impact · ${f.confidence}% confidence</p></div>`).join('')||'<p class="empty">No feature fits. Try increasing capacity.</p>'}<div class="row"><span>Total effort</span><strong>${b.effort} / ${state.capacity}</strong></div><div class="row"><span>Illustrative impact</span><strong>${b.impact}</strong></div><button id="apply" class="primary" ${!b.selected.length?'disabled':''}>Use this combination</button></div></div><div class="card" style="margin-top:22px"><h2>Scenario history</h2><p class="subtext">Saved in this browser. Snapshot values do not change when you adjust the current plan.</p>${state.history.map(s=>`<div class="history"><h3>${esc(s.names)} <span class="pill">${s.effort}/${s.capacity} pts</span></h3><p class="subtext">${esc(s.goal)} · ${esc(s.date)}</p></div>`).join('')||'<p class="empty">Save your first scenario to keep a comparison.</p>'}</div>`}else{content=`<div class="card brief"><div class="section-head"><h2>Your decision brief</h2><span class="pill">${a.fits?'Ready for review':'Capacity conflict'}</span></div><p>Northstar · ${esc(state.goal)} · ${a.effort} / ${state.capacity} capacity points</p><h2>Proposed selection</h2><p>${a.selected.map(f=>f.name).join(' + ')||'No features selected.'}</p>${!a.fits?'<div class="note warning">This selection exceeds capacity and is not ready to commit.</div>':''}<h2>Feasible comparison</h2><p>${recommendation(a)}</p><h2>Supporting evidence</h2>${a.selected.map(f=>`<p><strong>${f.name}</strong><br>${f.evidence}</p>`).join('')||'<p>Select features to include evidence.</p>'}<h2>Assumptions and risks</h2>${challenger(a).map(([h,p])=>`<p><strong>${esc(h)}</strong><br>${esc(p)}</p>`).join('')}<h2>Next steps</h2><p>Validate the evidence with customers, confirm scope and dependencies with engineering, and agree a measurable success metric and review date. The PM owns the final decision.</p><div class="note">Rule-based prototype. All evidence is synthetic. Impact scores are illustrative; dependencies and feature interactions are not modelled.</div><div class="actions"><button class="primary" id="download">Download brief ↓</button><button id="copy">Copy as Markdown</button><button data-nav="Prioritisation">Revise selection</button></div></div>`}$('#view').innerHTML=content;bind()}
function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));document.querySelectorAll('[data-feature]').forEach(el=>el.onchange=()=>{state.ids=el.checked?[...state.ids,el.dataset.feature]:state.ids.filter(id=>id!==el.dataset.feature);persist();render()});document.querySelectorAll('[data-evidence]').forEach(el=>el.onclick=()=>{const f=features.find(f=>f.id===el.dataset.evidence);$('#evidence-body').innerHTML=`<span class="pill">SYNTHETIC EVIDENCE</span><h2 style="margin-top:20px">${f.name}</h2><p>${f.evidence}</p><div class="note">Assumption: ${f.assumption}<br>Confidence: ${f.confidence}% · Impact: ${f.impact}/10 · Alignment: ${f.alignment}/10 for enterprise growth</div>`;$('#evidence').showModal()});if($('#capacity')){$('#capacity').oninput=e=>{$('#cap-value').innerHTML=`${e.target.value} <small>pts</small>`};$('#capacity').onchange=e=>{state.capacity=Number(e.target.value);persist();render();$('#capacity').focus()}}if($('#goal'))$('#goal').onchange=e=>{state.goal=e.target.value;persist();render()};if($('#apply'))$('#apply').onclick=()=>{state.ids=best(state.capacity,state.goal).selected.map(f=>f.id);persist();render();toast('Feasible combination applied')};if($('#save-scenario'))$('#save-scenario').onclick=()=>{const a=assess(state.ids,state.capacity,state.goal);state.history.unshift({names:a.selected.map(f=>f.name).join(' + ')||'No features',effort:a.effort,capacity:state.capacity,goal:state.goal,date:new Date().toLocaleString()});state.history=state.history.slice(0,10);persist();render();toast('Scenario saved in this browser')};if($('#download'))$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([briefText(assess(state.ids,state.capacity,state.goal))],{type:'text/markdown'}));const link=document.createElement('a');link.href=url;link.download='northstar-decision-brief.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if($('#copy'))$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(briefText(assess(state.ids,state.capacity,state.goal)));toast('Brief copied')}catch{toast('Clipboard unavailable. Use Download brief instead.')}}}
$('#brief-top').onclick=()=>navigate('Decision brief');$('#reset').onclick=()=>{state=defaults();persist();navigate('Overview');toast('Demo reset')};render();
